data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_04a098304b2031ab016ae8a67aea0887d08b1e601893c46a0d","logprobs":[],"output_index":1,"sequence_number":3388,"text":"{\n  \"title\": \"Technical Product Manager, Life Sciences Data Platform\",\n  \"company\": \"Northstar Bioinformatics\",\n  \"seniority\": null,\n  \"location\": \"Remote within Canada\",\n  \"requirements\": [\n    {\n      \"text\": \"Own the roadmap and backlog for ingestion, schema reconciliation, reference data, entity resolution, lineage, and data-quality capabilities.\",\n      \"quote_or_span\": \"Own the roadmap and backlog for ingestion, schema reconciliation, reference\\ndata, entity resolution, lineage, and data-quality capabilities.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Run discovery with scientists, data stewards, customers, and engineers.\",\n      \"quote_or_span\": \"Run discovery with scientists, data stewards, customers, and engineers\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Turn stakeholder needs into requirements.\",\n      \"quote_or_span\": \"turn their needs into requirements\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Turn stakeholder needs into specifications.\",\n      \"quote_or_span\": \"turn their needs into requirements, specifications, user stories, acceptance\\ncriteria, release plans, and product demonstrations.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Turn stakeholder needs into user stories.\",\n      \"quote_or_span\": \"turn their needs into requirements, specifications, user stories, acceptance\\ncriteria, release plans, and product demonstrations.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Turn stakeholder needs into acceptance criteria.\",\n      \"quote_or_span\": \"turn their needs into requirements, specifications, user stories, acceptance\\ncriteria, release plans, and product demonstrations.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Turn stakeholder needs into release plans.\",\n      \"quote_or_span\": \"turn their needs into requirements, specifications, user stories, acceptance\\ncriteria, release plans, and product demonstrations.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Turn stakeholder needs into product demonstrations.\",\n      \"quote_or_span\": \"turn their needs into requirements, specifications, user stories, acceptance\\ncriteria, release plans, and product demonstrations.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Define API contracts for new data connectors.\",\n      \"quote_or_span\": \"Define API contracts, mappings, transformations, validation rules, and\\nmeasurable outcomes for new data connectors.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Define mappings for new data connectors.\",\n      \"quote_or_span\": \"Define API contracts, mappings, transformations, validation rules, and\\nmeasurable outcomes for new data connectors.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Define transformations for new data connectors.\",\n      \"quote_or_span\": \"Define API contracts, mappings, transformations, validation rules, and\\nmeasurable outcomes for new data connectors.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Define validation rules for new data connectors.\",\n      \"quote_or_span\": \"Define API contracts, mappings, transformations, validation rules, and\\nmeasurable outcomes for new data connectors.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Define measurable outcomes for new data connectors.\",\n      \"quote_or_span\": \"Define API contracts, mappings, transformations, validation rules, and\\nmeasurable outcomes for new data connectors.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Guide engineering and quality-assurance teams through delivery.\",\n      \"quote_or_span\": \"Guide engineering and quality-assurance teams through delivery\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Make clear prioritization decisions across competing datasets and stakeholders.\",\n      \"quote_or_span\": \"making\\nclear prioritization decisions across competing datasets and stakeholders.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"behavioral\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Improve how canonical records are matched.\",\n      \"quote_or_span\": \"Improve how canonical records are matched, deduplicated, governed, and\\nsynchronized with external systems.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_grou