data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_056ee1b8e323a62a016ae8a6d1a37887d0b763a8000aac3e0b","logprobs":[],"output_index":1,"sequence_number":1067,"text":"{\n  \"summary\": {\n    \"text\": \"Clinical informatics and life-sciences data product leader whose 12 years of experience connect scientific requirements with engineering and delivery. Combines drug-reference and terminology expertise with data architecture and hands-on software delivery.\",\n    \"source_ids\": [\"sum-5111c6d8\"]\n  },\n  \"skills\": [\n    {\n      \"text\": \"customer discovery, backlog ownership, roadmap proposals, requirements, user stories, acceptance criteria, release planning, demonstrations\",\n      \"source_ids\": [\"skl-46fab4b1\"]\n    },\n    {\n      \"text\": \"reference data, canonical records, entity resolution, schema mapping, data quality, lineage, provenance, terminology, data catalogs\",\n      \"source_ids\": [\"skl-41750107\"]\n    },\n    {\n      \"text\": \"SQL, ETL pipelines, REST APIs, Python, PostgreSQL, Neo4j, Ruby, automated testing, continuous integration\",\n      \"source_ids\": [\"skl-f5c43ff6\"]\n    }\n  ],\n  \"roles\": [\n    {\n      \"role_key\": \"meridian-drug-knowledge\",\n      \"context\": {\n        \"text\": \"Partnered with scientists, customer teams, and engineers on a drug and clinical-reference platform while remaining hands-on in the production codebase.\",\n        \"source_ids\": [\"ctx-cd209614\"]\n      },\n      \"bullets\": [\n        {\n          \"text\": \"Owned the team backlog and wrote epics, user stories, acceptance criteria, and demonstrations for clinical-data and reference-data capabilities.\",\n          \"source_ids\": [\"b-e02c8105\"]\n        },\n        {\n          \"text\": \"Gathered customer and scientific requirements, proposed roadmap priorities, and translated ambiguous domain needs into technical specifications for engineering and quality assurance.\",\n          \"source_ids\": [\"b-4a42c4b0\"]\n        },\n        {\n          \"text\": \"Led delivery of a terminology classification service, defining review rules and measurable coverage while routing uncertain cases to scientific review.\",\n          \"source_ids\": [\"b-49f3d437\"]\n        },\n        {\n          \"text\": \"Designed canonical-record and entity-resolution rules across drug, condition, protein, and clinical-trial sources, preserving source identifiers and provenance.\",\n          \"source_ids\": [\"b-902e8b89\"]\n        },\n        {\n          \"text\": \"Built and maintained SQL, Python, and Ruby pipelines to map, validate, and load external reference datasets into PostgreSQL and Neo4j.\",\n          \"source_ids\": [\"b-87abdca3\"]\n        },\n        {\n          \"text\": \"Specified REST API payloads, schema mappings, validation rules, and backward-compatible releases for downstream customer integrations.\",\n          \"source_ids\": [\"b-0e09662d\"]\n        },\n        {\n          \"text\": \"Documented data definitions, lineage, and data-quality constraints in a catalog used by engineering and customer teams.\",\n          \"source_ids\": [\"b-dda626ca\"]\n        }\n      ]\n    },\n    {\n      \"role_key\": \"national-formulary-cooperative\",\n      \"context\": {\n        \"text\": \"Led technical delivery for national drug-information products, connecting pharmacy practice, editorial policy, and software teams.\",\n        \"source_ids\": [\"ctx-61b15573\"]\n      },\n      \"bullets\": [\n        {\n          \"text\": \"Managed roadmap proposals and publishing backlogs for drug-reference databases and APIs under an informatics title.\",\n          \"source_ids\": [\"b-2d93876a\"]\n        },\n        {\n          \"text\": \"Authored functional requirements, workflow specifications, validation rules, and acceptance criteria for publishing and customer-integration changes.\",\n          \"source_ids\": [\"b-44ea72a5\"]\n        },\n        {\n      